<template><section class="local-accounts"><h1>公众号账号</h1><p>账号凭据加密保存在你自己的部署中。配置公众号后，可在研究文章或选品流程选择草稿与正式发表。</p><p v-if="notice" role="status">{{ notice }}</p><form @submit.prevent="create"><label>公众号名称<input v-model="name" required maxlength="128"></label><button :disabled="busy || !auth.can('wechat.write')">添加公众号</button></form><article v-for="account in accounts" :key="account.accountId"><h2>{{ account.accountName }}</h2><p>{{ account.configured?'凭据已配置':'等待配置凭据' }} · {{ account.allowPublish?'账号允许正式发表':'账号仅用于草稿' }}</p><form @submit.prevent="save(account)"><label>AppID<input v-model="forms[account.accountId].appId" required autocomplete="off"></label><label>AppSecret<input v-model="forms[account.accountId].appSecret" type="password" required autocomplete="new-password"></label><button :disabled="busy || !auth.can('wechat.write')">保存加密凭据</button></form><label class="check"><input v-model="forms[account.accountId].allowPublish" type="checkbox">允许此账号提交正式发表（同时需要部署开关开放）</label><div class="actions"><button @click="mode(account)" :disabled="busy || !auth.can('wechat.write')">更新账号发表授权</button><button class="secondary" @click="probe(account)" :disabled="busy || !auth.can('wechat.write')">检查微信连接</button><button class="secondary" @click="revoke(account)" :disabled="busy || !auth.can('wechat.write')">撤销凭据</button></div></article></section></template>
<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue'
import request from '@/utils/request'
import {useAuthStore} from '@/stores/auth'
const auth=useAuthStore(),accounts=ref<any[]>([]),forms=reactive<Record<string,any>>({}),name=ref(''),notice=ref(''),busy=ref(false)
async function load(){const r:any=await request.get('/wechat-workspace/accounts');accounts.value=r.data||[];for(const a of accounts.value)forms[a.accountId]={appId:a.platformAccountId||'',appSecret:'',allowPublish:a.allowPublish}}
async function act(fn:()=>Promise<unknown>,message:string){busy.value=true;notice.value='';try{await fn();await load();notice.value=message}catch(e:any){notice.value=e.response?.data?.message||'操作失败'}finally{busy.value=false}}
function uuid(){const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`}
const create=()=>act(()=>request.post('/wechat-workspace/accounts',{requestId:uuid(),accountName:name.value}),'公众号已添加')
const save=(a:any)=>act(()=>request.put(`/wechat-workspace/accounts/${a.accountId}/credential`,{appId:forms[a.accountId].appId,appSecret:forms[a.accountId].appSecret}),'凭据已加密保存')
const mode=(a:any)=>act(()=>request.put(`/wechat-workspace/accounts/${a.accountId}`,{accountName:a.accountName,allowPublish:forms[a.accountId].allowPublish}),'账号授权已更新')
const probe=(a:any)=>act(()=>request.post(`/wechat-workspace/accounts/${a.accountId}/probe`),'Token连接正常；本次没有上传图片或发表文章')
const revoke=(a:any)=>act(()=>request.delete(`/wechat-workspace/accounts/${a.accountId}/credential`),'凭据已撤销')
onMounted(load)
</script><style scoped>.local-accounts{max-width:1100px;margin:auto;color:#34452c}.local-accounts p{line-height:1.9;color:#718064}.local-accounts article{background:white;border:1px solid #dfe5d8;border-radius:14px;padding:24px;margin-top:24px}.local-accounts form{display:flex;gap:16px;align-items:end;flex-wrap:wrap}.local-accounts label{display:grid;gap:8px;font-size:13px;flex:1;min-width:180px}.local-accounts input{padding:11px;border:1px solid #dfe5d8;border-radius:7px;font:inherit;min-width:0;width:100%;box-sizing:border-box}.local-accounts button{padding:11px 16px;background:#49664a;color:white;border:1px solid #49664a;border-radius:7px;cursor:pointer}.local-accounts button:disabled{opacity:.5}.local-accounts .secondary{background:white;color:#49664a}.local-accounts .check{display:flex;align-items:center;margin:22px 0;line-height:1.8}.check input{width:16px}.actions{display:flex;gap:10px;flex-wrap:wrap}</style>
